import itertools

def check_coloring(n, coloring):
    """
    Checks if a given coloring results in exactly 2007 monochromatic triples summing to a multiple of n.
    'coloring' is a list/array of size n+1, where coloring[i] is the color of i (0 for Red, 1 for Blue).
    """
    N_total = 0
    # Iterate over all n^3 triples
    for x in range(1, n + 1):
        for y in range(1, n + 1):
            for z in range(1, n + 1):
                # Check same color
                if coloring[x] == coloring[y] == coloring[z]:
                    # Check sum divisible by n
                    if (x + y + z) % n == 0:
                        N_total += 1
    return N_total

def search_unbalanced(n, target, max_k):
    if n < 1:
        return None

    found_n = None

    # Iterate over the size of the minority set B (k)
    for k in range(max_k + 1):
        # Iterate over all subsets B of size k
        for B_elements in itertools.combinations(range(1, n + 1), k):
            coloring = [0] * (n + 1)

            # Assign Blue color (1) to elements in B
            for x in B_elements:
                coloring[x] = 1

            # Remaining elements are Red (0)

            count = check_coloring(n, coloring)

            if count == target:
                # We found a solution for n
                return n

    return None

TARGET = 2007

# Check n=45 first, as n^2 = 2025 is closest to 2007.
# We limit k=2 to keep runtime reasonable.
n_candidate = 45
found_n = search_unbalanced(n_candidate, TARGET, max_k=2)

if found_n is None:
    # If 45 fails, we might check 46 or 44, but the search space grows extremely fast.
    # Since 45 is the strongest candidate based on n^2 ~ 2007, we stop here.
    print(f"No solution found for n=45 with |B| <= 2.")
else:
    print(f"Found solution for n={found_n}")

